-- CYCLE-005 reconciliation migration.
-- Exact historical SQL was not recoverable; this reconstructs observed live invariants.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('sales_invoices','sales_invoices_currency_nonblank','CHECK ((currency IS NOT NULL) AND (btrim(currency) <> ''''))'),('sales_invoices','sales_invoices_discount_nonnegative','CHECK (discount_amount >= 0)'),('sales_invoices','sales_invoices_subtotal_nonnegative','CHECK (subtotal >= 0)'),('sales_invoices','sales_invoices_tax_nonnegative','CHECK (tax_amount >= 0)'),('sales_invoices','sales_invoices_total_nonnegative','CHECK (total >= 0)'),('sales_invoices','sales_invoices_paid_nonnegative','CHECK (paid_amount >= 0)'),('sales_invoices','sales_invoices_nonnegative_amounts','CHECK (COALESCE(subtotal,0) >= 0 AND COALESCE(discount_amount,0) >= 0 AND COALESCE(tax_amount,0) >= 0 AND COALESCE(total,0) >= 0 AND COALESCE(paid_amount,0) >= 0)'),
    ('purchase_invoices','purchase_invoices_currency_nonblank','CHECK ((currency IS NOT NULL) AND (btrim(currency) <> ''''))'),('purchase_invoices','purchase_invoices_discount_nonnegative','CHECK (discount_amount >= 0)'),('purchase_invoices','purchase_invoices_subtotal_nonnegative','CHECK (subtotal >= 0)'),('purchase_invoices','purchase_invoices_tax_nonnegative','CHECK (tax_amount >= 0)'),('purchase_invoices','purchase_invoices_total_nonnegative','CHECK (total >= 0)'),('purchase_invoices','purchase_invoices_paid_nonnegative','CHECK (paid_amount >= 0)'),('purchase_invoices','purchase_invoices_nonnegative_amounts','CHECK (COALESCE(subtotal,0) >= 0 AND COALESCE(discount_amount,0) >= 0 AND COALESCE(tax_amount,0) >= 0 AND COALESCE(total,0) >= 0 AND COALESCE(paid_amount,0) >= 0)'),
    ('sale_items','sale_items_cost_price_nonnegative','CHECK (cost_price >= 0)'),('sale_items','sale_items_discount_nonnegative','CHECK (discount_amount >= 0)'),('sale_items','sale_items_line_total_nonnegative','CHECK (line_total >= 0)'),('sale_items','sale_items_quantity_nonnegative','CHECK (quantity >= 0)'),('sale_items','sale_items_tax_nonnegative','CHECK (tax_amount >= 0)'),('sale_items','sale_items_unit_price_nonnegative','CHECK (unit_price >= 0)'),('sale_items','sale_items_nonnegative_amounts','CHECK (COALESCE(unit_price,0) >= 0 AND COALESCE(discount_amount,0) >= 0 AND COALESCE(tax_amount,0) >= 0 AND COALESCE(line_total,0) >= 0 AND COALESCE(cost_price,0) >= 0)'),
    ('purchase_items','purchase_items_discount_nonnegative','CHECK (discount_amount >= 0)'),('purchase_items','purchase_items_line_total_nonnegative','CHECK (line_total >= 0)'),('purchase_items','purchase_items_quantity_nonnegative','CHECK (quantity >= 0)'),('purchase_items','purchase_items_tax_nonnegative','CHECK (tax_amount >= 0)'),('purchase_items','purchase_items_unit_price_nonnegative','CHECK (unit_price >= 0)'),('purchase_items','purchase_items_nonnegative_amounts','CHECK (COALESCE(unit_price,0) >= 0 AND COALESCE(discount_amount,0) >= 0 AND COALESCE(tax_amount,0) >= 0 AND COALESCE(line_total,0) >= 0)'),
    ('payments','payments_amount_nonnegative','CHECK (amount >= 0)'),('payments','payments_amount_positive','CHECK (amount > 0)'),('payments','payments_currency_nonblank','CHECK ((currency IS NOT NULL) AND (btrim(currency) <> ''''))'),('payments','payments_date_not_future','CHECK (payment_date <= CURRENT_DATE)'),('payments','payments_direction_valid','CHECK (direction = ANY (ARRAY[''IN'',''OUT'',''in'',''out'']))'),
    ('inventory_movements','inventory_movements_date_not_future','CHECK (movement_date <= CURRENT_DATE)'),('inventory_movements','inventory_movements_quantity_nonnegative','CHECK (quantity >= 0)'),('inventory_movements','inventory_movements_quantity_positive','CHECK (quantity > 0)'),('inventory_movements','inventory_movements_unit_cost_nonnegative','CHECK (unit_cost >= 0)'),('inventory_balances','inventory_balances_last_movement_not_future','CHECK (last_movement_date IS NULL OR last_movement_date <= CURRENT_DATE)'),('inventory_balances','inventory_balances_quantity_nonnegative','CHECK (quantity >= 0)'),('inventory_balances','inventory_balances_unit_cost_nonnegative','CHECK (unit_cost >= 0)'),
    ('business_intelligence_decisions','decisions_confidence_range','CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1))'),('business_intelligence_decisions','decisions_evidence_object','CHECK (jsonb_typeof(evidence) = ''object'')'),('business_intelligence_decisions','decision_approval_consistency','CHECK ((status = ''APPROVED'' AND approved_at IS NOT NULL AND approved_by IS NOT NULL) OR status <> ''APPROVED'')'),('business_intelligence_decisions','decision_approved_temporal_ck','CHECK (approved_at IS NULL OR approved_at >= created_at)'),('business_intelligence_decisions','decision_execution_consistency','CHECK ((status = ''EXECUTED'' AND executed_at IS NOT NULL) OR status <> ''EXECUTED'')'),
    ('decision_approvals','approvals_evidence_object','CHECK (jsonb_typeof(evidence) = ''object'')'),('decision_approvals','decision_approval_temporal_ck','CHECK (decided_at IS NULL OR decided_at >= requested_at)'),('decision_work_items','work_item_temporal_ck','CHECK ((started_at IS NULL OR started_at >= created_at) AND (completed_at IS NULL OR completed_at >= created_at) AND (completed_at IS NULL OR started_at IS NULL OR completed_at >= started_at) AND updated_at >= created_at)'),('decision_outcomes','decision_outcome_has_value','CHECK (expected_value IS NOT NULL OR actual_value IS NOT NULL)'),('decision_outcomes','decision_outcome_observed_before_recorded','CHECK (observed_at <= created_at)'),('decision_outcomes','decision_outcome_label_values','CHECK (label = ANY (ARRAY[''correct'',''incorrect'',''partial'',''unknown'']))'),('recommendation_outcomes','recommendation_outcome_evidence_object','CHECK (jsonb_typeof(evidence) = ''object'')'),('recommendations','recommendations_evidence_object','CHECK (evidence IS NOT NULL AND jsonb_typeof(evidence) = ''object'')')
  ) AS x(table_name,constraint_name,constraint_sql) LOOP
    IF to_regclass('public.'||r.table_name) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid=to_regclass('public.'||r.table_name) AND c.conname=r.constraint_name) THEN
      EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I %s',r.table_name,r.constraint_name,r.constraint_sql);
    END IF;
  END LOOP;
END $$;
